begin;
set local search_path=public,extensions;
select plan(24);

select ok((select bool_and(p.prosecdef and p.proconfig @> array['search_path=pg_catalog']) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('enforce_catalog_version_snapshot_lifecycle','enforce_catalog_release_item_lifecycle')),'snapshot lifecycle guards are SECURITY DEFINER with fixed pg_catalog search_path');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname in ('enforce_catalog_version_snapshot_lifecycle','enforce_catalog_release_item_lifecycle','authorize_catalog_version_lifecycle','authorize_catalog_version_attestation') and (has_function_privilege('anon',p.oid,'EXECUTE') or has_function_privilege('authenticated',p.oid,'EXECUTE') or has_function_privilege('service_role',p.oid,'EXECUTE'))) and not has_table_privilege('anon','private.catalog_version_write_capabilities','SELECT') and not has_table_privilege('authenticated','private.catalog_version_write_capabilities','INSERT') and not has_table_privilege('service_role','private.catalog_version_write_capabilities','DELETE'),'guards, capability issuers and capability storage are inaccessible to every API runtime role');
select has_trigger('public','catalog_library_versions','catalog_library_snapshot_lifecycle_guard','library snapshot lifecycle trigger exists');
select has_trigger('public','catalog_category_versions','catalog_category_snapshot_lifecycle_guard','category snapshot lifecycle trigger exists');
select has_trigger('public','catalog_subcategory_versions','catalog_subcategory_snapshot_lifecycle_guard','subcategory snapshot lifecycle trigger exists');
select has_trigger('public','catalog_service_versions','catalog_service_snapshot_lifecycle_guard','service snapshot lifecycle trigger exists');
select has_trigger('public','catalog_service_subcategory_link_versions','catalog_link_snapshot_lifecycle_guard','link snapshot lifecycle trigger exists');
select has_trigger('public','catalog_release_items','catalog_release_items_00_lifecycle_guard','release item lifecycle trigger exists');

