('e2900000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-lifecycle@example.invalid','',now(),'{}','{}',now(),now()),
('e2900000-0000-0000-0000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p06-reviewer@example.invalid','',now(),'{}','{}',now(),now());
