select throws_ok($$update public.catalog_library_versions set name_fr='Mutation interdite' where id='e2970000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','approved library payload is immutable');
select throws_ok($$update public.catalog_category_versions set code='MUTATED_CAT' where id='e2980000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','approved category snapshot identity is immutable');
select throws_ok($$update public.catalog_subcategory_versions set category_id='e2930000-0000-0000-0000-000000000001',content_hash=repeat('a',64) where id='e2990000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','approved subcategory payload and hash are immutable');
select throws_ok($$update public.catalog_service_versions set slug='mutated-service' where id='e29a0000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','approved service snapshot identity is immutable');
select throws_ok($$update public.catalog_service_subcategory_link_versions set link_type='SECONDARY' where id='e29b0000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','approved link snapshot is immutable');
select throws_ok($$update public.catalog_category_versions set translation_review_status='APPROVED',translation_reviewer_user_id='e2900000-0000-0000-0000-000000000001',translation_reviewed_at=clock_timestamp(),translation_review_proof_hash=repeat('a',64),translation_review_version=1,row_version=row_version+1 where id='e2980000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','direct attestation-shaped update without capability is rejected');
create temporary table p06_lifecycle_errors(key text primary key,sqlstate text,message text);
grant insert on p06_lifecycle_errors to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2900000-0000-0000-0000-000000000002","role":"authenticated"}',true);
do $runtime$begin
  perform public.attest_catalog_ar_translation('CATEGORY','e2980000-0000-0000-0000-000000000001',repeat('a',64),1,'p06-lifecycle-no-aal','e29d0000-0000-0000-0000-000000000002');
exception when others then insert into p06_lifecycle_errors values('missing-aal',sqlstate,sqlerrm);end$runtime$;
reset role;
select is((select sqlstate||':'||message from p06_lifecycle_errors where key='missing-aal'),'42501:TRANSLATION_REVIEW_DENIED','missing AAL claim fails closed before attestation');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"e2900000-0000-0000-0000-000000000002","role":"authenticated","aal":"aal2"}',true);
select public.attest_catalog_ar_translation('CATEGORY','e2980000-0000-0000-0000-000000000001',repeat('a',64),1,'p06-lifecycle-attest','e29d0000-0000-0000-0000-000000000001');
reset role;
select ok((select translation_review_status='APPROVED' and translation_reviewer_user_id='e2900000-0000-0000-0000-000000000002' and translation_review_proof_hash=repeat('a',64) and translation_review_version=1 from public.catalog_category_versions where id='e2980000-0000-0000-0000-000000000001'),'authorized MFA attestation RPC writes the exact reviewer and proof');
select ok((select count(*) from public.audit_events where action='catalog.translation.attested' and resource_id='e2980000-0000-0000-0000-000000000001')=1 and (select count(*) from public.event_outbox where event_type='CatalogArabicTranslationAttestedV1' and aggregate_id='e2980000-0000-0000-0000-000000000001')=1,'attestation RPC emits one audit event and one Outbox event');
select throws_ok($$update public.catalog_service_versions set status='PUBLISHED',published_at=clock_timestamp(),row_version=row_version+1 where id='e29a0000-0000-0000-0000-000000000001'$$,'55000','IMMUTABLE_CATALOG_SNAPSHOT','direct lifecycle-shaped update without capability is rejected');

