update public.catalog_releases set status='PUBLISHING' where id='e29c0000-0000-0000-0000-000000000011';select private.activate_catalog_release_items('e29c0000-0000-0000-0000-000000000011');
select ok((select status='RETIRED' from public.catalog_service_versions where id='e29a0000-0000-0000-0000-000000000001') and (select status='PUBLISHED' from public.catalog_service_versions where id='e29a0000-0000-0000-0000-000000000002'),'legitimate activation retires the previous version and publishes the next');
select private.activate_catalog_release_items('e29c0000-0000-0000-0000-000000000010');
